/**
 * Normalizes search text by removing diacritics/accents, lowercasing, and trimming whitespace.
 * e.g., 'Citroen' -> 'citroen', 'Skoda' -> 'skoda', 'diesel' -> 'diesel'.
 */
export function normalizeSearchText(str) {
  return (str || '')
    .toString()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

export function getAllCatalogBrands() {
  return VEHICLE_CATALOG.map((b) => ({
    id: b.id,
    name: b.name,
    group: b.group,
    country: b.country,
    countryFlag: b.countryFlag,
    badge: b.badge,
    modelCount: b.models.length,
    engineCount: b.models.reduce((acc, m) => acc + m.engines.length, 0),
  }));
}

export function getModelsForBrand(brandNameOrId) {
  if (!brandNameOrId || brandNameOrId === 'All Brands') return [];
  const q = normalizeSearchText(brandNameOrId);
  const b = VEHICLE_CATALOG.find(
    (x) => normalizeSearchText(x.id) === q || normalizeSearchText(x.name) === q
  );
  return b ? b.models : [];
}

export function getEnginesForModel(brandNameOrId, modelNameOrId) {
  const models = getModelsForBrand(brandNameOrId);
  const q = normalizeSearchText(modelNameOrId);
  const m = models.find(
    (x) => normalizeSearchText(x.id) === q || normalizeSearchText(x.name) === q
  );
  return m ? m.engines : [];
}

export function findEngineById(engineId) {
  for (const b of VEHICLE_CATALOG) {
    for (const m of b.models) {
      for (const e of m.engines) {
        if (e.id === engineId) return e;
      }
    }
  }
  return null;
}

/**
 * Locates the exact brand and model hierarchy given an engine preset ID.
 * Returns { brand, model, engine } or null.
 */
export function findCatalogHierarchyByEngineId(engineId) {
  for (const b of VEHICLE_CATALOG) {
    for (const m of b.models) {
      for (const e of m.engines) {
        if (e.id === engineId) {
          return { brand: b, model: m, engine: e };
        }
      }
    }
  }
  return null;
}

/**
 * High-precision multi-token, diacritic-insensitive catalog search.
 * Searches across Brand, Model, Generation, Engine name, Engine code, Fuel, Body, and Defect tags.
 */
export function searchCatalog(query) {
  const normQuery = normalizeSearchText(query);
  if (!normQuery) return [];

  const tokens = normQuery.split(/\s+/).filter(Boolean);
  const results = [];

  for (const b of VEHICLE_CATALOG) {
    for (const m of b.models) {
      for (const e of m.engines) {
        const corpus = normalizeSearchText([
          b.name,
          b.badge,
          b.group,
          m.name,
          m.generations,
          e.name,
          e.shortName,
          e.engineCode,
          e.fuelType,
          e.bodyType,
          e.powertrainLabel,
          e.criticalDefectTag,
          e.knownRiskNotes,
        ].join(' '));

        const matches =
          corpus.includes(normQuery) ||
          (tokens.length > 1 && tokens.every((tok) => corpus.includes(tok)));

        if (matches) {
          results.push({
            engine: e,
            brand: b,
            model: m,
          });
        }
      }
    }
  }
  return results;
}

export function getAllEnginesFlat() {
  const flat = [];
  for (const b of VEHICLE_CATALOG) {
    for (const m of b.models) {
      for (const e of m.engines) {
        flat.push(e);
      }
    }
  }
  return flat;
}
